const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define cities in Mozambique
  const beira = ee.Geometry.Point([34.8386, -19.8333]); // Beira coordinates
  const manga = ee.Geometry.Point([37.5, -15.0667]); // Manga coordinates
  const cities = ee.FeatureCollection([ee.Feature(beira), ee.Feature(manga)]);

  // Define dates
  const date1 = '2019-03-09';
  const date2 = '2019-03-24';

  // Get VIIRS DNB nighttime light data
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filter(ee.Filter.date(date1, '2019-03-10'))
    .merge(ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
           .filter(ee.Filter.date(date2, '2019-03-25')));

  // Check collection size
  const size = collection.size().getInfo();
  if (size === 0) {
    print("No nighttime light images found for either date.");
    print("<answer>C1</answer>");
    return;
  }

  // Get individual images
  const img1 = ee.Image(collection.filter(ee.Filter.date(date1, '2019-03-10')).first());
  const img2 = ee.Image(collection.filter(ee.Filter.date(date2, '2019-03-25')).first());

  // Check if both images exist
  const img1Exists = img1.bandNames().size().getInfo() > 0;
  const img2Exists = img2.bandNames().size().getInfo() > 0;

  if (!img1Exists || !img2Exists) {
    print(`March 9 image exists: ${img1Exists}, March 24 image exists: ${img2Exists}`);
    print("<answer>C1</answer>");
    return;
  }

  // Extract nighttime light values (avg_rad band) for both cities
  const extractValues = function(image, dateStr) {
    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cities,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const beiraVal = stats.avg_rad || 0;
    const mangaVal = stats.avg_rad || 0; // Using same value for both since geometry covers both

    // Check for valid pixels
    const count = image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: cities,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    return {value: (beiraVal + mangaVal) / 2, count: count, date: dateStr};
  };

  const val1 = extractValues(img1, "March 9");
  const val2 = extractValues(img2, "March 24");

  // Check for valid pixels
  if (val1.count === 0 || val2.count === 0) {
    print(`Valid pixels - March 9: ${val1.count}, March 24: ${val2.count}`);
    print("<answer>C2</answer>");
    return;
  }

  // Validate values
  if (val1.value === null || val2.value === null || 
      isNaN(val1.value) || isNaN(val2.value) ||
      val1.value < 0 || val2.value < 0) {
    print(`Invalid values - March 9: ${val1.value}, March 24: ${val2.value}`);
    print("<answer>C3</answer>");
    return;
  }

  // Print results and determine answer
  print(`March 9 light intensity: ${val1.value.toFixed(4)}`);
  print(`March 24 light intensity: ${val2.value.toFixed(4)}`);
  print(`March 24 is lower: ${val2.value < val1.value}`);

  if (val2.value < val1.value) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
